// GET /api/p101/vibration?minutes=5
// Liefert die Messwerte der letzten Minuten (Standard 5, höchstens 60) als JSON.
msg.headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*",   // Webapp auf GitHub Pages darf abfragen
    "Cache-Control": "no-store"
};

const db = flow.get("p101db");
if (!db) {
    msg.statusCode = 503;
    msg.payload = { error: "Datenbank nicht bereit" };
    return msg;
}

let minutes = parseInt(msg.req.query.minutes, 10);
if (!Number.isFinite(minutes)) minutes = 5;
minutes = Math.min(Math.max(minutes, 1), 60);

const seit = Date.now() - minutes * 60 * 1000;
const rows = db.prepare("SELECT ts, value FROM vibration WHERE ts >= ? ORDER BY ts").all(seit);

msg.statusCode = 200;
msg.payload = {
    source: "P-101 Vibration",
    unit: "mm/s",
    minutes: minutes,
    count: rows.length,
    data: rows.map(r => ({ timestamp: new Date(r.ts).toISOString(), value: r.value }))
};
return msg;

// Durchschnitt der letzten Minuten (Standard 5, höchstens 60).
// Kommt die Nachricht vom REST-Endpunkt (msg.req), geht die Antwort an Ausgang 1.
// Kommt sie vom Zeitgeber, geht ein Text an das Dashboard (Ausgang 2).
const db = flow.get("p101db");
const vomRest = !!msg.req;

if (vomRest) {
    msg.headers = {
        "Content-Type": "application/json",
        "Access-Control-Allow-Origin": "*",   // Webapp auf GitHub Pages darf abfragen
        "Cache-Control": "no-store"
    };
}
if (!db) {
    if (!vomRest) return null;
    msg.statusCode = 503;
    msg.payload = { error: "Datenbank nicht bereit" };
    return [msg, null];
}

let minutes = vomRest ? parseInt(msg.req.query.minutes, 10) : 5;
if (!Number.isFinite(minutes)) minutes = 5;
minutes = Math.min(Math.max(minutes, 1), 60);
const seit = Date.now() - minutes * 60 * 1000;

const r = db.prepare(`
    SELECT AVG(value) AS avg, MIN(value) AS min, MAX(value) AS max, COUNT(*) AS n
    FROM vibration
    WHERE ts >= ?
`).get(seit);

const runden = v => (v === null || v === undefined) ? null : Math.round(v * 1000) / 1000;
const ergebnis = {
    source: "P-101 Vibration",
    unit: "mm/s",
    minutes: minutes,
    count: r.n,
    average: runden(r.avg),
    min: runden(r.min),
    max: runden(r.max)
};

if (vomRest) {
    msg.statusCode = 200;
    msg.payload = ergebnis;
    return [msg, null];
}
const text = ergebnis.count
    ? ergebnis.average.toFixed(2).replace(".", ",") + " mm/s (" + ergebnis.count + " Werte)"
    : "noch keine Werte";
node.status({ text: "Ø " + text });
return [null, { payload: text }];

// Wertet jede Nachricht unter /bbk-lf7/<kiste>/power-house/vibration aus,
// auch die eigene. Je Topic wird festgehalten, wie oft, in welchem Format und mit welchen Werten gesendet wird.
const teile = msg.topic.split("/");
const stelle = teile.indexOf("bbk-lf7");
const kiste = stelle >= 0 ? teile[stelle + 1] : "?";
const roh = Buffer.isBuffer(msg.payload) ? msg.payload.toString("utf8") : String(msg.payload);

let format = "Text", wert = null, felder = [];
try {
    const obj = JSON.parse(roh);
    if (typeof obj === "number") {
        format = "Zahl";
        wert = obj;
    } else if (obj && typeof obj === "object") {
        format = Array.isArray(obj) ? "JSON-Liste" : "JSON-Objekt";
        felder = Array.isArray(obj) ? [] : Object.keys(obj).sort();
        // Wert direkt (value, vibration, …) oder verschachtelt wie im rohen OPC-UA-DataValue (value.value)
        const innen = obj.value && typeof obj.value === "object" ? obj.value.value : undefined;
        const kandidat = [obj.value, obj.vibration, obj.wert, obj.payload, innen].find(v => typeof v === "number");
        if (kandidat !== undefined) wert = kandidat;
        if (innen !== undefined) format = "JSON-Objekt (OPC-UA-DataValue)";
    } else {
        format = "JSON (" + typeof obj + ")";
    }
} catch (e) {
    if (/^\s*-?\d+([.,]\d+)?\s*$/.test(roh)) {
        format = "Zahl als Text";
        wert = parseFloat(roh.replace(",", "."));
    }
}

const EIGENE_KISTE = "18";
const jetzt = Date.now();
const alle = flow.get("gruppen") || {};
const g = alle[msg.topic] || {
    topic: msg.topic, kiste: kiste, eigene: kiste === EIGENE_KISTE,
    anzahl: 0, erste: jetzt, bytes: 0, retained: 0, formate: {}, felder: [],
    min: null, max: null, summe: 0, werteAnzahl: 0
};
g.anzahl++;
g.letzte = jetzt;
g.bytes += Buffer.byteLength(roh);
if (msg.retain) g.retained++;
g.formate[format] = (g.formate[format] || 0) + 1;
g.felder = [...new Set(g.felder.concat(felder))].sort();
if (wert !== null && Number.isFinite(wert)) {
    g.min = g.min === null ? wert : Math.min(g.min, wert);
    g.max = g.max === null ? wert : Math.max(g.max, wert);
    g.summe += wert;
    g.werteAnzahl++;
    g.letzterWert = wert;
}
g.beispiel = roh.slice(0, 300);
alle[msg.topic] = g;
flow.set("gruppen", alle);

const fremde = Object.values(alle).filter(x => !x.eigene).length;
node.status({ fill: fremde ? "green" : "grey", shape: "dot", text: fremde + " fremde Gruppen gehört" });
msg.kiste = kiste;
msg.format = format;
return msg;

// GET /api/bbk-lf7/gruppen: Vergleich aller gehörten Topics als JSON
msg.headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*",
    "Cache-Control": "no-store"
};
const jetzt = Date.now();
const runden = v => (v === null || v === undefined) ? null : Math.round(v * 1000) / 1000;
const alle = Object.values(flow.get("gruppen") || {});
msg.payload = {
    seit: alle.length ? new Date(Math.min(...alle.map(g => g.erste))).toISOString() : null,
    gruppen: alle.sort((a, b) => a.topic.localeCompare(b.topic, "de", { numeric: true })).map(g => {
        const sekunden = Math.max((g.letzte - g.erste) / 1000, 1);
        return {
            topic: g.topic,
            kiste: g.kiste,
            eigene: g.eigene,
            nachrichten: g.anzahl,
            proMinute: g.anzahl > 1 ? Math.round((g.anzahl - 1) / sekunden * 60 * 10) / 10 : null,
            zuletztVorSekunden: Math.round((jetzt - g.letzte) / 1000),
            durchschnittBytes: Math.round(g.bytes / g.anzahl),
            retained: g.retained,
            formate: g.formate,
            felder: g.felder,
            werte: g.werteAnzahl ? { min: runden(g.min), max: runden(g.max), durchschnitt: runden(g.summe / g.werteAnzahl), letzter: runden(g.letzterWert) } : null,
            beispiel: g.beispiel
        };
    })
};
msg.statusCode = 200;
return msg;

// Messwert für das Dashboard aufbereiten:
// Ausgang 1: Zahl für Tacho und Diagramm, Ausgang 2: Text mit Wert und Uhrzeit
const wert = msg.payload.value;
const zeit = new Date(msg.payload.timestamp).toLocaleTimeString("de-DE", { timeZone: "Europe/Berlin" });
return [
    { payload: Math.round(wert * 100) / 100, topic: "P-101" },
    { payload: wert.toFixed(2).replace(".", ",") + " mm/s um " + zeit }
];

// Extra 1: Grenzwerte überwachen, mit Entwarnungsschwelle (Hysterese).
// Eine Stufe gilt, bis der Wert unter ihre niedrigere Entwarnungsschwelle fällt.
// Pendelt der Wert knapp um eine Grenze, bleibt es deshalb bei genau einer Meldung.
//   Warnung ab 4,5 mm/s, Entwarnung erst unter 4,0 mm/s
//   Alarm   ab 7,1 mm/s, Entwarnung erst unter 6,5 mm/s
// Ausgang 1: Meldung, nur wenn sich die Stufe ändert
// Ausgang 2: aktueller Zustand als Text fürs Dashboard (bei jedem Wert)
// Ausgang 3: Ergebnis der Testfolge (Inject "Test: Werte pendeln um 7,1")
const GRENZEN = {
    warnung: { an: 4.5, aus: 4.0 },
    alarm:   { an: 7.1, aus: 6.5 }
};
const STUFEN = ["normal", "warnung", "alarm"];
const NAMEN = ["Normal", "Warnung", "Alarm"];
const TOPIC = "/bbk-lf7/18/power-house/vibration/alarm";

function neueStufe(alt, wert) {
    if (wert >= GRENZEN.alarm.an) return 2;
    if (alt === 2 && wert >= GRENZEN.alarm.aus) return 2;
    if (wert >= GRENZEN.warnung.an) return 1;
    if (alt >= 1 && wert >= GRENZEN.warnung.aus) return 1;
    return 0;
}

const komma = (v, stellen) => v.toFixed(stellen).replace(".", ",");
const zeitpunkt = iso => {
    const d = new Date(iso);
    const tz = { timeZone: "Europe/Berlin" };
    const heute = d.toLocaleDateString("de-DE", tz) === new Date().toLocaleDateString("de-DE", tz);
    return (heute ? "" : d.toLocaleDateString("de-DE", { ...tz, day: "2-digit", month: "2-digit" }) + " ") +
        d.toLocaleTimeString("de-DE", tz);
};

// Meldung beim Wechsel von Stufe alt auf Stufe neu
function meldung(alt, neu, wert, timestamp) {
    let ereignis, grenze, text;
    if (neu > alt) {
        const g = GRENZEN[STUFEN[neu]];
        ereignis = NAMEN[neu];
        grenze = g.an;
        text = `${ereignis}: ${komma(wert, 2)} mm/s (ab ${komma(g.an, 1)}). Entwarnung erst unter ${komma(g.aus, 1)} mm/s.`;
    } else if (neu === 1) {
        ereignis = "Entwarnung";
        grenze = GRENZEN.alarm.aus;
        text = `Entwarnung Alarm: ${komma(wert, 2)} mm/s (unter ${komma(grenze, 1)}). Warnung bleibt bis unter ${komma(GRENZEN.warnung.aus, 1)} mm/s.`;
    } else {
        ereignis = "Entwarnung";
        grenze = GRENZEN.warnung.aus;
        text = `Entwarnung: ${komma(wert, 2)} mm/s (unter ${komma(grenze, 1)}). Wieder normal.`;
    }
    return { art: "alarm", ereignis, zustand: STUFEN[neu], vorher: STUFEN[alt], wert, grenze, text, timestamp };
}

// Testfolge mit eigenem Zustand durchspielen, der echte Zustand bleibt unberührt
if (msg.topic === "test") {
    const werte = msg.payload;
    let stufe = 0, ohne = 0, ohneSchwelle = 0;
    const meldungen = [];
    for (const w of werte) {
        const neu = neueStufe(stufe, w);
        if (neu !== stufe) meldungen.push(meldung(stufe, neu, w, new Date().toISOString()).text);
        stufe = neu;
        // Zum Vergleich: dieselben Grenzen ohne Entwarnungsschwelle
        const o = w >= GRENZEN.alarm.an ? 2 : w >= GRENZEN.warnung.an ? 1 : 0;
        if (o !== ohne) ohneSchwelle++;
        ohne = o;
    }
    return [null, null, { payload: { werte, meldungen, anzahl: meldungen.length, ohneEntwarnungsschwelle: ohneSchwelle } }];
}

const wert = msg.payload.value;
let z = context.get("zustand");
if (!z) {
    // Nach Deploy oder Neustart mit der zuletzt gemeldeten Stufe weitermachen,
    // damit ein laufender Alarm nicht ein zweites Mal gemeldet wird
    const db = flow.get("p101db");
    const letzte = db && db.prepare("SELECT ts, zustand FROM meldung WHERE art = 'alarm' ORDER BY ts DESC LIMIT 1").get();
    z = letzte
        ? { stufe: Math.max(0, STUFEN.indexOf(letzte.zustand)), seit: new Date(letzte.ts).toISOString() }
        : { stufe: 0, seit: null };
}

const neu = neueStufe(z.stufe, wert);
let aus1 = null;
if (neu !== z.stufe) {
    aus1 = { topic: TOPIC, payload: meldung(z.stufe, neu, wert, msg.payload.timestamp) };
    z = { stufe: neu, seit: msg.payload.timestamp };
}
context.set("zustand", z);

// Aktueller Zustand für den REST-Endpunkt /api/p101/meldungen
flow.set("p101alarm", { zustand: STUFEN[z.stufe], seit: z.seit, wert, timestamp: msg.payload.timestamp });

const text = NAMEN[z.stufe] + (z.seit ? " seit " + zeitpunkt(z.seit) : "");
node.status({ fill: ["green", "yellow", "red"][z.stufe], shape: "dot", text });
return [aus1, { payload: text }, null];

// Extra 2: Ausfall erkennen (Watchdog).
// Eingang: jeder Messwert und alle 2 s ein Takt (topic "takt").
// Kommt länger als 10 s kein Messwert, geht genau einmal "Ausfall" raus,
// beim ersten Wert danach genau einmal "Wieder da".
// Ausgang 1: Meldung, nur beim Wechsel
// Ausgang 2: Zustand als Text fürs Dashboard (bei jedem Takt)
const GRENZE_MS = 10 * 1000;   // Milo schickt jede Sekunde einen Wert
const START_MS = 30 * 1000;    // nach Deploy oder Neustart dauert es länger bis zum ersten Wert
const TOPIC = "/bbk-lf7/18/power-house/vibration/status";

const jetzt = Date.now();
const zeitpunkt = ms => {
    const d = new Date(ms);
    const tz = { timeZone: "Europe/Berlin" };
    const heute = d.toLocaleDateString("de-DE", tz) === new Date(jetzt).toLocaleDateString("de-DE", tz);
    return (heute ? "" : d.toLocaleDateString("de-DE", { ...tz, day: "2-digit", month: "2-digit" }) + " ") +
        d.toLocaleTimeString("de-DE", tz);
};
const dauer = ms => {
    const s = Math.round(ms / 1000);
    if (s < 120) return s + " s";
    if (s < 2 * 3600) return Math.round(s / 60) + " min";
    if (s < 2 * 86400) return Math.round(s / 3600) + " h";
    return Math.round(s / 86400) + " Tage";
};

let z = context.get("zustand");
if (!z) {
    // Nach Deploy oder Neustart: War zuletzt ein Ausfall gemeldet, gilt er weiter,
    // bis wieder ein Wert kommt. Sonst beginnt die Überwachung jetzt.
    const db = flow.get("p101db");
    const letzte = db && db.prepare("SELECT ts, zustand FROM meldung WHERE art = 'ausfall' ORDER BY ts DESC LIMIT 1").get();
    const offen = letzte && letzte.zustand === "ausfall";
    // Gemeldet wurde der Ausfall 10 s nach dem letzten Wert
    z = { start: jetzt, letzter: null, ausfall: !!offen, seit: offen ? letzte.ts - GRENZE_MS : null };
}

function meldung(ereignis, text, wert) {
    return {
        topic: TOPIC,
        payload: {
            art: "ausfall",
            ereignis,
            zustand: z.ausfall ? "ausfall" : "ok",
            seit: z.seit ? new Date(z.seit).toISOString() : null,
            wert: wert === undefined ? null : wert,
            text,
            timestamp: new Date(jetzt).toISOString()
        }
    };
}

let aus1 = null;
if (msg.topic === "takt") {
    const bezug = z.letzter || z.start;
    const grenze = z.letzter ? GRENZE_MS : START_MS;
    if (!z.ausfall && jetzt - bezug > grenze) {
        z.ausfall = true;
        z.seit = bezug;
        aus1 = meldung("Ausfall", z.letzter
            ? `Ausfall: Seit ${zeitpunkt(z.letzter)} kommen keine Messwerte vom OPC-UA-Server.`
            : `Ausfall: Seit dem Start um ${zeitpunkt(z.start)} kam kein Messwert vom OPC-UA-Server.`);
    }
} else {
    if (z.ausfall) {
        const lang = dauer(jetzt - z.seit);
        z.ausfall = false;
        aus1 = meldung("Wieder da", `Wieder da: Messwerte kommen wieder (${msg.payload.value.toFixed(2).replace(".", ",")} mm/s), Ausfall dauerte ${lang}.`, msg.payload.value);
    }
    z.letzter = jetzt;
    z.seit = null;
}
context.set("zustand", z);

// Aktueller Zustand für den REST-Endpunkt /api/p101/meldungen
flow.set("p101datenfluss", {
    zustand: z.ausfall ? "ausfall" : "ok",
    seit: z.seit ? new Date(z.seit).toISOString() : null,
    letzterWert: z.letzter ? new Date(z.letzter).toISOString() : null
});

if (msg.topic !== "takt") return [aus1, null];
let text;
if (z.ausfall) text = `Ausfall seit ${zeitpunkt(z.seit)} (${dauer(jetzt - z.seit)})`;
else if (z.letzter) text = `Werte kommen, letzter vor ${dauer(jetzt - z.letzter)}`;
else text = "Warte auf den ersten Wert";
node.status({ fill: z.ausfall ? "red" : z.letzter ? "green" : "grey", shape: "dot", text });
return [aus1, { payload: text }];

// Jede Meldung (Alarm, Warnung, Entwarnung, Ausfall, Wieder da) in die Tabelle "meldung" schreiben
const db = flow.get("p101db");
if (!db) {
    node.error("Datenbank ist nicht geöffnet", msg);
    return null;
}
const m = msg.payload;
db.prepare("INSERT INTO meldung (ts, art, ereignis, zustand, wert, text) VALUES (?, ?, ?, ?, ?, ?)")
    .run(Date.parse(m.timestamp) || Date.now(), m.art, m.ereignis, m.zustand, m.wert ?? null, m.text);

// Meldungen älter als 7 Tage löschen
db.prepare("DELETE FROM meldung WHERE ts < ?").run(Date.now() - 7 * 24 * 60 * 60 * 1000);

const anzahl = db.prepare("SELECT COUNT(*) AS n FROM meldung").get().n;
node.status({ fill: "green", shape: "dot", text: anzahl + " Meldungen gespeichert" });
return null;

// Meldung als Popup im Dashboard anzeigen, Farbe je nach Ereignis
const FARBEN = {
    "Alarm": "#ff5c5c",
    "Warnung": "#f5b942",
    "Entwarnung": "#3ddc84",
    "Ausfall": "#ff5c5c",
    "Wieder da": "#3ddc84"
};
return {
    payload: msg.payload.text,
    ui_update: { color: FARBEN[msg.payload.ereignis] || "#6aa8ee" }
};

// GET /api/p101/meldungen?minutes=60
// Liefert den aktuellen Zustand (Extra 1 und 2) und die Meldungen der letzten Minuten
// (Standard 60, höchstens 1440 = 24 Stunden), neueste zuerst.
msg.headers = {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*",   // Webapp auf GitHub Pages darf abfragen
    "Cache-Control": "no-store"
};

const db = flow.get("p101db");
if (!db) {
    msg.statusCode = 503;
    msg.payload = { error: "Datenbank nicht bereit" };
    return msg;
}

let minutes = parseInt(msg.req.query.minutes, 10);
if (!Number.isFinite(minutes)) minutes = 60;
minutes = Math.min(Math.max(minutes, 1), 1440);

const seit = Date.now() - minutes * 60 * 1000;
const rows = db.prepare(`
    SELECT ts, art, ereignis, zustand, wert, text
    FROM meldung
    WHERE ts >= ?
    ORDER BY ts DESC
    LIMIT 200
`).all(seit);

msg.statusCode = 200;
msg.payload = {
    source: "P-101 Vibration",
    zustand: {
        grenzwerte: flow.get("p101alarm") || null,
        datenfluss: flow.get("p101datenfluss") || null
    },
    minutes: minutes,
    count: rows.length,
    data: rows.map(r => ({
        timestamp: new Date(r.ts).toISOString(),
        art: r.art,
        ereignis: r.ereignis,
        zustand: r.zustand,
        wert: r.wert,
        text: r.text
    }))
};
return msg;
